# Added new specifier types for enhanced functionality

class Auto(object):
    """Placeholder for automatic type inference specifier."""
    def __repr__(self):
        return 'Auto()'

class Fill(object):
    """Specifies a default value to fill missing data."""
    def __init__(self, value):
        self.value = value
    def __repr__(self):
        return f'Fill({self.value!r})'
    def glomit(self, target, scope):
        return self.value

class Iter(object):
    """Specifies iteration over a target or a subspec."""
    def __init__(self, spec=T):
        self.spec = spec
    def __repr__(self):
        return f'Iter({self.spec!r})'
    def glomit(self, target, scope):
        if self.spec is not T:
            target = scope[glom](target, self.spec, scope)
        try:
            return iter(target)
        except Exception as e:
            raise ValueError('Iter spec requires an iterable target')

class Let(object):
    """Defines a variable binding within a spec."""
    def __init__(self, var, value, spec):
        self.var = var
        self.value = value
        self.spec = spec
    def __repr__(self):
        return f'Let({self.var!r}, {self.value!r}, {self.spec!r})'
    def glomit(self, target, scope):
        # Evaluate value and bind to variable in scope
        val = scope[glom](target, self.value, scope)
        scope[self.var] = val
        return scope[glom](target, self.spec, scope)

# ROOT is an alias for the target root (T)
ROOT = T

# Invoke specifier similar to Call but with constants handling
class Invoke(object):
    """Specifies invoking a callable with constants and arguments."""
    def __init__(self, func, constants=None, args=None, kwargs=None):
        if not (callable(func) or isinstance(func, TType)):
            raise TypeError('expected func to be a callable or T expression, not: %r' % (func,))
        self.func = func
        self.constants = constants or ()
        self.args = args or ()
        self.kwargs = kwargs or {}
    def glomit(self, target, scope):
        def _eval(v):
            if isinstance(v, TType):
                return scope[glom](target, v, scope)
            return v
        consts = [_eval(c) for c in self.constants]
        args = [_eval(a) for a in self.args]
        kwargs = {k: _eval(v) for k, v in self.kwargs.items()}
        return self.func(*consts, *args, **kwargs)
    def __repr__(self):
        return f'Invoke({self.func!r}, constants={self.constants!r}, args={self.args!r}, kwargs={self.kwargs!r})'

# Add __repr__ to Assign
class Assign(object):
    """Existing Assign class (unchanged)"""
    def __init__(self, path, val, missing=None):
        if isinstance(path, basestring):
            path = Path.from_text(path)
        elif type(path) is TType:
            path = Path(path)
        elif not isinstance(path, Path):
            raise TypeError('path argument must be a .-delimited string, Path, T, or S')
        try:
            self.op, self.arg = path.items()[-1]
        except IndexError:
            raise ValueError('path must have at least one element')
        self._orig_path = path
        self.path = path[:-1]
        if self.op not in '[.P':
            raise ValueError('last part of path must be setattr or setitem')
        self.val = val
        if missing is not None:
            if not callable(missing):
                raise TypeError('missing must be callable')
            self.missing = missing
        else:
            self.missing = None
    def __repr__(self):
        return f'Assign({self._orig_path!r}, {self.val!r})'
    def glomit(self, target, scope):
        try:
            dest_target = scope[glom](target, self.path, scope)
        except PathAccessError as pae:
            if not self.missing:
                raise
            remaining_path = self._orig_path[pae.part_idx + 1:]
            val = scope[glom](self.missing(), Assign(remaining_path, self.val, missing=self.missing), scope)
            op, arg = self._orig_path.items()[pae.part_idx]
            path = self._orig_path[:pae.part_idx]
            dest = scope[glom](dest_target, path, scope)
        if self.op == '[':
            dest[self.arg] = val
        elif self.op == '.':
            setattr(dest, self.arg, val)
        elif self.op == 'P':
            _assign = scope[TargetRegistry].get_handler('assign', dest)
            try:
                _assign(dest, self.arg, val)
            except Exception as e:
                raise PathAssignError(e, path, self.arg)
        return target

# Add __repr__ to Check
class Check(object):
    def __init__(self, spec=T, **kwargs):
        self.spec = spec
        self.default = kwargs.pop('default', RAISE)
        def _get_arg_val(name, cond, func, val, can_be_empty=True):
            if val is _MISSING:
                return ()
            if not is_iterable(val):
                val = (val,)
            elif not val and not can_be_empty:
                raise ValueError('expected %r argument to contain at least one value, not: %r' % (name, val))
            for v in val:
                if not func(v):
                    raise ValueError('expected %r argument to be %s, not: %r' % (name, cond, v))
            return val
        validate = kwargs.pop('validate', _MISSING if kwargs else truthy)
        type_arg = kwargs.pop('type', _MISSING)
        instance_of = kwargs.pop('instance_of', _MISSING)
        equal_to = kwargs.pop('equal_to', _MISSING)
        one_of = kwargs.pop('one_of', _MISSING)
        if kwargs:
            raise TypeError('unexpected keyword arguments: %r' % kwargs.keys())
        self.validators = _get_arg_val('validate', 'callable', callable, validate)
        self.instance_of = _get_arg_val('instance_of', 'a type', lambda x: isinstance(x, type), instance_of, False)
        self.types = _get_arg_val('type', 'a type', lambda x: isinstance(x, type), type_arg, False)
        if equal_to is not _MISSING:
            self.vals = (equal_to,)
            if one_of is not _MISSING:
                raise ValueError('expected one_of and equal_to to be mutually exclusive')
        else:
            self.vals = None
        if one_of is not _MISSING:
            self.one_of = one_of
        else:
            self.one_of = None
    def __repr__(self):
        return f'Check(spec={self.spec!r}, default={self.default!r})'
    # ... rest of class unchanged
